  "主题": "Theme",
  "决定 DockStart 使用深色还是浅色界面。选择「跟随系统」后，会随 Windows 的浅色/深色设置自动切换。": "Determines whether DockStart uses a dark or light interface. After selecting \"Follow system\", it will automatically switch with the light/dark settings of Windows.",
