  "主题模式": "Theme Mode",
  "与本机偏好一起保存，重新启动 DockStart 后仍然生效。": "Saved with local preferences and still take effect after restarting DockStart.",
  "外观": "Appearance",
  "在不改变 DockStart 视觉语言的前提下调整明暗反差与面板层级。所有页面共用同一套配色变量，因此整个软件会一起变化。": "Adjust light and dark contrast and panel hierarchy without changing the DockStart visual language. All pages share the same set of color variables, so the entire software changes together.",
  "强调色": "Accent color",
  "只调整按钮、选中态与键盘焦点等强调用的颜色。成功、警告、错误、分子与 Vina 等语义色不会改变，避免影响科学信息的可读性。": "Only adjust the accent colors for buttons, selected states, and keyboard focus. Semantic colors such as success, warning, error, molecule, and Vina will not change to avoid affecting the readability of scientific information.",
  "启动页面": "Startup page",
  "下次启动生效；未加载项目时显示项目入口，不自动打开历史文件。": "It will take effect next time it is started; when the project is not loaded, the project entry will be displayed and the history file will not be automatically opened.",
