  "工具与运行环境": "Tools and runtime",
  "DockStart 实际使用的 Python 与 AutoDock Vina。留空时继续自动检测。": "DockStart actually uses Python and AutoDock Vina. Leave blank to continue automatic detection.",
  "Python 解释器": "Python interpreter",
  "DockStart 后端（结构准备、PDBQT 转换等）使用的 Python 3 解释器。留空时按内置版本、系统环境依次自动检测，不会使用 MGLTools 自带的 Python 2.7。": "Python 3 interpreter used by the DockStart backend (structure preparation, PDBQT conversion, etc.). If left blank, it will be automatically detected according to the built-in version and system environment in order, and the Python 2.7 that comes with MGLTools will not be used.",
