  "Python 路径已保存。": "Python path saved.",
  "Python 路径已清空，恢复自动检测。": "The Python path has been cleared and automatic detection is restored.",
  "执行分子对接的可执行文件。DockStart 需要 AutoDock Vina 1.2.x；留空时优先使用随应用附带的内置版本，其次才使用系统 PATH 中的 vina。": "Executable file for molecular docking. DockStart requires AutoDock Vina 1.2.x; when left blank, the built-in version shipped with the application will be used first, followed by the vina in the system PATH.",
