  "评分函数": "Scoring function",
  "对接打分使用的评分函数。Vina 是标准评分函数；Vinardo 对疏水匹配更敏感。AD4 maps 需要 AutoGrid4 亲和力图，只能在批量筛选流程中单独选择，不能设为默认评分函数。": "Scoring function used for docking scoring. Vina is the standard scoring function; Vinardo is more sensitive to hydrophobic matches. AD4 maps require AutoGrid4 affinity maps, which can only be selected individually during the batch screening process and cannot be set as the default scoring function.",
