  "柔性残基允许受体部分侧链在对接时发生构象变化。通常只选择与结合口袋直接相关、且有合理结构依据的少量残基；不要机械地把所有邻近残基都设为柔性。第一次使用或没有明确结构依据时，可以保持默认的刚性受体。": "Flexible residues allow part of the receptor side chain to change pose during docking. Typically select only a small number of residues that are directly relevant to the binding pocket and have a reasonable structural basis; do not mechanically make all neighboring residues flexible. The default rigid receptor can be kept when used for the first time or when there is no clear structural basis.",
  "两种模式下，配体始终按 Vina 标准柔性处理（可旋转键自动保留）。区别只在于受体是否允许少量残基参与柔性变化。": "In both modes, ligand is always processed according to Vina standard flexibility (rotatable bonds are automatically retained). The only difference lies in whether the receptor allows a small number of residues to participate in flexible changes.",
  "标准对接": "Standard docking",
  "：受体刚性 + 配体柔性。受体不发生侧链柔性变化，配体仍按 Vina 标准保留可旋转键，无需选择柔性残基。": ": receptor rigid + ligand flexible. The receptor does not undergo side chain flexibility changes, and the ligand still retains the rotatable bond according to the Vina standard, without the need to select flexible residues.",
  "受体有限柔性对接": "Receptor limited flexibility docking",
  "：受体部分柔性 + 配体柔性。在标准对接的基础上，额外允许选定少量受体残基发生柔性变化。": ": receptor partially flexible + ligand flexible. On the basis of standard docking, additional flexibility changes are allowed for a small number of selected receptor residues.",
  "受体柔性模式": "Receptor flexible mode",
  "有限柔性": "Limited flexibility",
  "柔性残基（最多 8 个）": "Flexible residues (up to 8)",
  "例如 A:315, A:381 或 A:315:B": "For example A:315, A:381 or A:315:B",
  "格式：A:315；带插入码时使用 A:315:B。": "Format: A:315; use A:315:B when inserting code.",
