  "这不是串行批量筛选。每个 Mode 同时包含两个成员，Vina 只给出整个联合体系的一个评分， 不提供单个成员的独立贡献。": "This is not a serial batch screening. Each Mode contains two members at the same time. Vina only gives a score for the entire joint system and does not provide the independent contribution of a single member.",
