  "搜索范围（Box）是 Vina 的搜索空间，用中心点（center）和边长（size）描述，单位均为 Å。它限定了 Vina 在哪里寻找可能的结合构象，并不等同于真实结合位点本身。Box 过小可能遗漏合理构象，过大则会扩大搜索范围和计算成本。": "The search range (Box) is the search space of Vina, which is described by the center point (center) and the side length (size), and the unit is Å. It qualifies where Vina looks for possible binding poses and is not equivalent to the actual binding site itself. If the Box is too small, reasonable poses may be missed, while if the Box is too large, the search range and calculation cost will be expanded.",
