  "RMSD 描述整组联合构象相对 Mode 1 的差异；标为“仅日志”的评分行被 energy_range 排除，没有可加载的 out.pdbqt 构象。": "RMSD describes the difference of the entire set of joint poses relative to Mode 1; the scoring row marked \"log only\" is excluded by energy_range and there is no out.pdbqt pose to load.",
  "RMSD 相对基于 Mode 1 的构象，仅用于本次输出内比较。": "RMSD is relative to the pose based on Mode 1, and is only used for comparison within this output.",
  "评分与 RMSD": "Score and RMSD",
  "Affinity（评分）：Vina 给出的预测结合评分，单位 kcal/mol。数值越小通常代表预测结合越强，但只用于在同一次计算中比较候选构象，不能拿不同体系或不同条件的分数直接比较。RMSD：描述不同对接构象之间的结构差异。不要把 RMSD 简单理解成“越小就一定越好”，它只是衡量构象间偏离程度的参考指标。": "Affinity: Predicted binding score given by Vina in kcal/mol. The smaller the value usually means the stronger the prediction combination, but it is only used to compare candidate poses in the same calculation, and the scores of different systems or different conditions cannot be directly compared. RMSD: describes the structural differences between different docking poses. Don’t simply understand RMSD as “the smaller the better”, it is just a reference indicator to measure the degree of deviation between poses.",
