  "Vina 使用随机搜索与局部优化，而不是遗传算法。Vina 与 Vinardo 的分值不能直接横向比较。": "Vina uses random search with local optimization instead of genetic algorithm. Vina and Vinardo scores cannot be directly compared side by side.",
  "这些 Box 与适用的 Vina 参数会冻结到每个配体任务中；显式未结合态参考能量不适用于批量全局对接。修改后需要重新创建队列。": "These Boxes and applicable Vina parameters are frozen into each ligand task; explicit unbound state reference energies do not apply to batch global docking. The queue needs to be re-created after modification.",
  "这些 Box 与 Vina 参数会冻结到一个联合 run；两个成员不会分别运行，也不会产生可独立解释的成员评分。": "These Box and Vina parameters are frozen into a joint run; the two members do not run separately and do not produce independently interpretable member scores.",
