  "串行批量 AD4 仅支持标准 AutoDock4 maps；AD4Zn 与水合协议仍使用各自的单配体工作流。": "Serial batch AD4 only supports standard AutoDock4 maps; AD4Zn and hydration protocols still use their own single ligand workflows.",
