  "空": "Empty",
  "（无选择器）": "(no selector)",
  "本协议的 affinity 与 RMSD 均属于两个配体组成的联合构象；DockStart 不提供单个配体的独立评分贡献。": "Both affinity and RMSD of this protocol belong to a joint pose composed of two ligands; DockStart does not provide independent scoring contribution of a single ligand.",
  "用户已取消多配体共同对接。": "The user has canceled multi-ligand joint docking.",
  "ATOM/HETATM 记录缺少可解析为有限数的 PDBQT partial charge。": "The ATOM/HETATM record is missing a PDBQT partial charge that can be parsed into a finite number.",
  "已解析 {0} 个两配体联合构象。": "{0} two ligand joint poses have been resolved.",
  "边界按 Vina 的 spacing 与整数网格体素数重建；与 Vina 1.2.7 的 is_in_grid 语义一致，只有可移动非氢原子越界才使结果失败。H/HD 越界会完整记录并提示，但不会把 Vina 已接受的构象误判为无效。": "Boundaries are reconstructed according to Vina's spacing with integer grid voxel numbers; consistent with Vina 1.2.7's is_in_grid semantics, only movable non-hydrogen atoms out of bounds cause the result to fail. H/HD cross-border will be fully recorded and prompted, but Vina's accepted pose will not be misjudged as invalid.",
  "连续 100 次无法分配唯一 run_id。": "Unable to assign unique run_id 100 times in a row.",
  "- 状态：{0}": "- Status: {0}",
  "- 评分协议：{0}": "- Scoring protocol: {0}",
  "- 评分函数：{0}": "- Scoring function: {0}",
  "- Vina 版本：{0}": "- Vina version: {0}",
  "- 联合构象数量：{0}": "- Joint pose quantity: {0}",
  "本报告来自一次 Vina 搜索中的两个配体共同优化，不是串行批量筛选。": "This report is from a Vina search co-optimizing two ligands, not a serial batch screening.",
  "当前实验版本仅支持两个唯一 PDBQT 配体、刚性受体、Vina/Vinardo 或标准 AutoDock4 maps 评分，以及全局搜索。": "The current experimental version only supports two unique PDBQT ligand, rigid receptor, Vina/Vinardo or standard AutoDock4 maps scoring, as well as global search.",
  "共同对接已完成，out.pdbqt 中有 {0} 个通过成员校验的联合构象。": "Joint docking has been completed, and there are {0} joint poses that passed membership verification in out.pdbqt.",
  "多配体共同对接运行状态已读取。": "The running status of multiple ligands jointly docking has been read.",
  "已加载联合 Mode {0} 的 member {1}；显示的 affinity 属于完整两配体联合构象。": "Member {1} of joint Mode {0} has been loaded; the displayed affinity belongs to the complete two ligand joint pose.",
  "多配体共同对接（实验性）报告内容已生成。": "Multi-ligand joint docking (experimental) report content generated.",
  "多配体共同对接（实验性）Markdown 报告已生成。": "Multi-ligand joint docking (experimental) Markdown report generated.",
  "两个配体都没有可用于 Vina 网格估算的原子类型。": "Neither ligand has an atom type available for Vina grid estimation.",
  "两个配体原子类型并集所需的 Vina 网格预计超过 DockStart 的 2 GiB 保护上限。": "The Vina mesh required for the union of two ligand atom types is expected to exceed DockStart's 2 GiB protection limit.",
  "冻结 AutoDock4 maps manifest 的间距、点数或实际尺寸无效。": "Freeze AutoDock4 maps manifest with invalid spacing, points, or actual dimensions.",
  "两个配体都没有可用于 AD4 maps 核对的原子类型。": "Neither ligand has an atom type that can be used for AD4 maps checking.",
  "两个配体合计 Vina 有效搜索扭转数为 {0}，超过当前实验协议允许的复杂度范围。": "The total Vina effective search twist number for both ligands is {0}, which exceeds the complexity range allowed by the current experimental protocol.",
  "共同对接的搜索空间包含 {0} 个显式自由度；当前 exhaustiveness={1} 低于实验协议复核建议值 {2}。请使用多个固定 seed 重复运行并比较联合构象稳定性。": "The joint docking search space contains {0} explicit degrees of freedom; the current exhaustiveness={1} is lower than the experimental protocol review recommendation of {2}. Please repeat the run with multiple fixed seeds and compare joint pose stability.",
  "Box 中心必须是有限数，三个尺寸必须是有限正数。": "The center of the Box must be a finite number, and the three dimensions must be finite positive numbers.",
  "至少一个刚性配体的重原子直径大于 Vina 有效网格对角线，任何刚体旋转都无法把该刚性构象完整放入。": "The heavy atom diameter of at least one rigid ligand is larger than the Vina effective grid diagonal, and any rigid body rotation cannot completely fit the rigid pose.",
  "至少一个配体按源文件当前朝向的轴向尺寸大于 Box 对应轴；全局搜索允许旋转，因此这只作为提示，不作为失败条件。请结合目标口袋与输出原子边界复核。": "The axial size of at least one ligand in the current orientation of the source file is larger than the corresponding axis of the Box; global search allows rotation, so this is only used as a prompt and not as a failure condition. Please review it in conjunction with the target pocket and output atom boundaries.",
  "源文件绝对位置和当前朝向不构成全局搜索硬门禁；只有刚性成员的重原子直径大于有效网格对角线才能证明该构象无法容纳；柔性成员不使用这一证明。重原子直径通过也不证明两个配体能同时得到合理构象。最终接受条件按 Vina 实际网格中的输出重原子复核。": "The absolute position and current orientation of the source file do not constitute a hard access control for global search; only the heavy atom diameter of the rigid member is larger than the effective grid diagonal can prove that the pose cannot be accommodated; this proof is not used for flexible members. The passing of heavy atom diameter does not prove that two ligands can obtain a reasonable pose at the same time. The final acceptance conditions are reviewed against the output heavy atoms in the actual grid of Vina.",
  "协议产物路径必须是项目相对路径：{0}": "The protocol product path must be a project relative path: {0}",
  "协议产物路径不存在：{0}": "Protocol product path does not exist: {0}",
