  "第 {0} 行的 BRANCH 端点必须是正整数。": "The BRANCH endpoint at line {0} must be a positive integer.",
  "第 {0} 个配体必须恰好包含一个 ROOT 和一个 ENDROOT。": "{0}th ligand must contain exactly one ROOT and one ENDROOT.",
  "第 {0} 个配体必须恰好包含一条 TORSDOF。": "{0}th ligand must contain exactly one TORSDOF.",
  "第 {0} 个配体的 TORSDOF 必须是单个非负整数。": "TORSDOF of ligand {0} must be a single non-negative integer.",
  "第 {0} 个配体的 TORSDOF 不能为负数。": "TORSDOF of ligand {0} cannot be negative.",
  "第 {0} 个配体的 TORSDOF 必须是最后一条非空记录。": "TORSDOF of ligand {0} must be the last non-null record.",
  "第 {0} 个配体必须至少包含一个非氢原子。": "{0}th ligand must contain at least one non-hydrogen atom.",
  "第 {0} 个配体包含 {1} 个原子，超过当前共同对接实验协议的单成员安全上限。": "The {0}th ligand contains {1} atoms, which exceeds the single-member safety limit of the current joint docking experimental protocol.",
  "第 {0} 个配体的 ROOT 块未闭合或不含原子。": "The ROOT block for ligand {0} is unclosed or contains no atoms.",
  "第 {0} 个配体存在未闭合的 BRANCH。": "There is an unclosed BRANCH in ligand {0}.",
  "联合构象 Mode {0} 必须恰好包含一条 REMARK VINA RESULT。": "Joint pose Mode {0} must contain exactly one REMARK VINA RESULT.",
  "联合构象 Mode {0} 的评分或 RMSD 不是有限数字。": "The score or RMSD for joint pose Mode {0} is not a finite number.",
  "联合构象 Mode {0} 必须恰好包含两个以 TORSDOF 结尾的成员块。": "Joint pose Mode {0} must contain exactly two member blocks ending with TORSDOF.",
  "共同对接输出 out.pdbqt 为空。": "Joint docking output out.pdbqt is empty.",
  "成员清单必须恰好包含两个冻结配体。": "The member list must contain exactly two frozen ligands.",
  "成员清单顺序无效；首版必须按 member 1、member 2 排列。": "The order of the member list is invalid; the first version must be arranged by member 1, member 2.",
  "联合构象 Mode {0} 缺少 ENDMDL。": "ENDMDL is missing for joint pose Mode {0}.",
  "out.pdbqt 中没有找到任何联合构象 MODEL。": "No joint pose MODEL found in out.pdbqt.",
  "冻结的 Box、spacing 或网格体素数无效。": "Invalid number of frozen Box, spacing, or mesh voxels.",
  "至少一个联合输出构象只有 H/HD 氢原子越出实际网格；Vina 的网格接受检查忽略氢原子，本次保留为审计警告。": "At least one joint output pose has only H/HD hydrogen atoms outside the actual grid; Vina's grid is checked and hydrogen atoms are ignored, this time it is retained as an audit warning.",
  "至少一个联合输出构象有可移动非氢原子越出 Vina 实际网格边界。": "At least one joint output pose has moveable non-hydrogen atoms outside the Vina actual grid boundary.",
  "多配体共同对接（实验性）首版必须恰好选择两个配体。": "Multiple ligands joint docking (experimental) First release must select exactly two ligands.",
  "两个配体的文件内容相同，不能组成共同对接输入。": "The file contents of the two ligands are the same and cannot form a joint docking input.",
  "项目尚未导入刚性受体 PDBQT。": "The project has not yet imported rigid receptor PDBQT.",
  "没有找到项目中的刚性受体 PDBQT。": "The rigid receptor PDBQT in the project was not found.",
  "刚性受体 PDBQT 没有可识别的 ATOM/HETATM 记录。": "The rigid receptor PDBQT has no identifiable ATOM/HETATM record.",
  "多配体共同对接（实验性）运行记录已准备；两个配体将进入同一次 Vina 全局搜索。": "Multi-ligand joint docking (experimental) run record prepared; two ligands will enter the same Vina global search.",
  "metadata 中的成员快照清单必须恰好包含两个配体。": "The member snapshot list in metadata must contain exactly two ligands.",
  "共同对接冻结的联合网格估算与两个配体原子类型并集不一致。": "Joint docking frozen joint mesh estimate is inconsistent with union of two ligand atom types.",
  "共同对接冻结的自由度风险记录与两个配体快照不一致。": "Joint docking frozen DOF risk record inconsistent with two ligand snapshots.",
  "共同对接冻结的 Box 几何覆盖记录与配体快照不一致。": "Joint docking frozen Box geometry coverage record inconsistent with ligand snapshot.",
  "搜索维度按 Vina 实际生成的非退化 PDBQT segment 计数；只有轴端原子且没有子分支的叶 BRANCH 不产生搜索扭转。TORSDOF 只作为来源声明记录，不是搜索维度，Vina/Vinardo 也不直接用它计算扭转项。该上限是 DockStart 当前实验协议边界，不是 Vina 硬上限。": "Search dimensions counted as non-degenerate PDBQT segments actually generated by Vina; leaf BRANCH with only axis-end atoms and no sub-branches does not produce search twist. TORSDOF is only used as a source declaration record, not a search dimension, and Vina/Vinardo does not directly use it to calculate the torsion term. This cap is the current experimental protocol boundary for DockStart, not a Vina hard cap.",
  "受体输入": "Receptor input",
  "配置快照": "Configuration snapshot",
  "stdout 评分表可能包含因 energy_range 过滤而未写入 out.pdbqt 的模式；“构象可加载”只以 out.pdbqt 中实际存在且通过成员校验的 MODEL 为准。": "The stdout score table may contain modes that are not written to out.pdbqt due to energy_range filtering; \"pose loadable\" is only based on the MODEL that actually exists in out.pdbqt and passes membership verification.",
  "RMSD 表示整个两配体联合构象相对最佳联合模式的差异，不是任一成员的单独 RMSD。": "RMSD represents the difference between the entire joint pose of two ligands relative to the optimal joint mode, not the individual RMSD of any one member.",
