  "请降低活动扭转数量，或改为分别对接。该限制是 DockStart 对实验协议的验证边界，不是 Vina 的硬上限。": "Please reduce the number of active twists, or dock them individually instead. This limit is DockStart's validation boundary for the experimental protocol, not a hard upper limit for Vina.",
