  "含仅有轴端原子的退化叶 BRANCH；Vina 会解析但不为这些叶分支创建搜索扭转，DockStart 已按同一规则排除。": "Contains degenerate leaf BRANCH with only axial end atoms; Vina resolves but does not create search twists for these leaf branches, DockStart has excluded by the same rules.",
  "的 PDBQT TORSDOF 声明与 Vina 有效搜索扭转数不同；二者语义不同，DockStart 只把 TORSDOF 作为来源声明记录。": "The PDBQT TORSDOF declaration is different from the Vina effective search torsion number; the semantics are different, and DockStart only records TORSDOF as a source declaration.",
  "无法读取共同对接冻结的 Box 中心或尺寸。": "Unable to read joint docking frozen Box center or dimensions.",
  "第 {0} 个配体的三维坐标记录不完整或范围无效。": "The three-dimensional coordinate record of the {0} ligand is incomplete or the range is invalid.",
  "请增大 Box，并确认扩大的区域仍对应目标结合位点；该阻断只适用于没有有效搜索扭转的刚性成员。": "Please increase the Box and confirm that the enlarged region still corresponds to the target binding site; this block only applies to rigid members without effective search torsion.",
  "的当前绝对坐标不完全位于 Box 内。Vina 全局搜索会移动配体，因此这不是阻断条件；仍需确认 Box 覆盖目标口袋，并在结果中复核原子是否越出 Box。": "The current absolute coordinates of are not entirely within the Box. The Vina global search moves the ligand, so this is not a blocking condition; you still need to confirm that the Box covers the target pocket, and check whether the atoms are outside the Box in the results.",
  "含有效搜索扭转；柔性构象可折叠或伸展，因此输入构象直径不作为无法容纳的硬门禁，最终按输出重原子边界复核。": "Contains effective search torsion; the flexible pose can be folded or extended, so the input pose diameter is not treated as a hard gate that cannot be accommodated, and is ultimately reviewed against the output heavy atom boundary.",
