  "### 配体运动（与冻结输入分别比较）": "### ligand motion (separate comparison with frozen input)",
  "### 柔性侧链运动（与各自冻结输入分别比较）": "### Flexible side chain motion (compared separately with respective frozen inputs)",
  "上述两组指标在同一受体坐标系中直接比较，没有做刚体对齐；配体指标包含整体平移、旋转和内部构象变化，柔性残基指标单独计算，并排除 H/HD/HS、非物理伪原子和 CA 根原子。": "The above two sets of indicators are directly compared in the same receptor coordinate system without rigid body alignment; the ligand indicator includes overall translation, rotation and internal pose changes, and the flexible residue indicators are calculated separately, and exclude H/HD/HS, non-physical pseudo atoms and CA root atoms.",
  "这些“直接 RMSD / 位移”不是 Vina 表格中相对 Mode 1 的 RMSD l.b./u.b.，也不是相对共晶配体的恢复 RMSD。": "These \"direct RMSD/displacements\" are not the RMSD l.b./u.b. relative to Mode 1 in the Vina tables, nor are they the recovered RMSD relative to the co-crystal ligand.",
  "运动大小与 docking score 只描述本次输入和协议下的计算结果，不能单独证明真实结合、构象合理性或药效。": "Movement size and docking score only describe the calculation results under this input and protocol, and cannot independently prove the true combination, pose rationality or drug efficacy.",
  "### 配体与柔性侧链运动": "### ligand and flexible side chain motion",
  "- 本次使用 AutoDock4Zn beta：TZ 是几何伪原子，Vina 通过 AD4Zn 专用 maps 以 `--scoring ad4` 运行；该评分不能与标准 AutoDock4、Vina 或 Vinardo 直接横向比较。": "- This time using AutoDock4Zn beta: TZ is a geometric pseudo-atom and Vina is run with `--scoring ad4` via AD4Zn-specific maps; the scoring is not directly comparable side-by-side with standard AutoDock4, Vina or Vinardo.",
  "- 本次使用 Vina/Vinardo 预计算 maps；运行命令未传入 --receptor，最终优化和评分只使用网格，不使用显式受体原子。": "- This time Vina/Vinardo is used to precompute maps; the --receptor is not passed in the running command, and only the grid is used for final optimization and scoring, without explicit receptor atoms.",
  "- 本次配体使用经过人工确认、合同与 worker 证据交叉校验的 Meeko 大环准备；确认的断环键和 G* 数量只说明本次 PDBQT 的闭环约束实现，不证明所选构象、质子化、电荷或结合模式正确。": "- This ligand is prepared using Meeko macrocycle that has been manually confirmed and cross-checked with contract and worker evidence; the number of confirmed ring-breaking bonds and G* only illustrates the closed-loop constraint implementation of this PDBQT, and does not prove that the selected pose, protonation, charge or binding mode is correct.",
  "- 对接后的 PDBQT 不是原始闭环化学拓扑；用于 SDF 或后续分析前，仍须使用受支持的 Meeko 拓扑重建流程并人工检查闭环与立体化学。": "- The docked PDBQT is not the original closed-loop chemical topology; loop closure and stereochemistry must still be manually checked using the supported Meeko topology reconstruction pipeline before use in SDF or subsequent analysis.",
